/**
 * Jinx Ogre + Recluse: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Ogre
 * Wiki: https://wiki.bloodontheclocktower.com/Recluse
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L108, M41). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { castWith, run } from '#lib/core/model/fixtures.test-support.ts';
import { becomesOffer } from '#lib/core/rules/becomes.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { scenario } from '#lib/core/testing/scenario.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});

describe('Ogre + Recluse jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'ogre', 'recluse');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('ogre')?.name).toBe('Ogre');
		expect(data.byId.get('recluse')?.name).toBe('Recluse');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['ogre', 'recluse'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['ogre'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['recluse'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: if the Recluse registers as evil to the Ogre, the Ogre is
	// evil and learns it. Whether the Recluse registers so is its own ability's call, so the
	// Recluse's side needs no jinx data to offer it.
	describe('the Ogre who chooses the Recluse may become evil', () => {
		const cast = castWith({
			script: scriptOf(['ogre', 'recluse', 'imp', 'chef', 'empath', 'poisoner'])
		});
		const friend = { characterId: 'ogre', label: 'Friend' };

		it('needs no jinx data for the Recluse: its own ability covers the registration', () => {
			expect(jinxRulesBetween('recluse', 'ogre')).toBeUndefined();
		});

		it('offers to make the Ogre evil when its Friend is the Recluse', () => {
			const { game, ctx, seats } = cast(['ogre', 'recluse', 'imp', 'chef', 'empath']);
			expect(becomesOffer(game, seats[1], friend, ctx.characters)).toEqual({
				into: 'alignment',
				seatId: seats[0],
				characterId: 'ogre',
				alignment: 'evil'
			});
			// A good Friend who registers truly changes nothing.
			expect(becomesOffer(game, seats[3], friend, ctx.characters)).toBeUndefined();
		});

		it('offers nothing when the Recluse is poisoned', () => {
			const { session, ctx, seats } = cast(['ogre', 'recluse', 'imp', 'chef', 'poisoner']);
			const { game } = run(session, ctx, {
				type: 'AddReminder',
				seatId: seats[1],
				reminder: { characterId: 'poisoner', label: 'Poisoned' }
			});
			expect(becomesOffer(game, seats[1], friend, ctx.characters)).toBeUndefined();
		});
	});

	// Both pages' Related Jinxes: the Ogre usually never learns which alignment they took on.
	// Here, made evil by a Recluse Friend registering as evil, they do: the Ogre's step says so.
	describe('the Ogre made evil by the Recluse learns they are evil', () => {
		const script = scriptOf(['ogre', 'recluse', 'imp', 'chef', 'empath', 'poisoner']);
		const base = scenario(['ogre', 'recluse', 'imp', 'chef', 'empath'], { script });
		const madeEvil = (at: typeof base) =>
			({ type: 'SetAlignment', seatId: at.seat('ogre'), alignment: 'evil' }) as const;
		const learns = (s: typeof base) =>
			nightStepAlerts(s.game, 'ogre', s.characters).filter((a) => a.kind === 'learns-alignment');

		it("is data in the Ogre's rules", () => {
			expect(jinxRulesBetween('ogre', 'recluse')).toEqual({
				learns: {
					what: 'alignment',
					when: [{ partnerMarked: 'Friend' }, { alignment: 'evil' }]
				}
			});
		});

		it("is a learns-alignment alert at the Ogre's step once the Ogre is evil", () => {
			// Wiki: "If the Recluse registers as evil to the Ogre, the Ogre learns that they are evil."
			const evil = base.reminder('recluse', 'ogre', 'Friend').do(madeEvil);
			expect(learns(evil)).toEqual([
				expect.objectContaining({
					seatId: evil.seat('ogre'),
					source: { characterId: 'ogre', seatId: evil.seat('ogre') },
					partner: 'recluse',
					alignment: 'evil'
				})
			]);
		});

		it('learns nothing when the Recluse registers as good', () => {
			// Wiki: "If the Recluse registers as evil to the Ogre, the Ogre learns that they are evil."
			expect(learns(base.reminder('recluse', 'ogre', 'Friend'))).toEqual([]);
		});

		it('learns nothing when the Friend is another evil player', () => {
			// Wiki: "If the Recluse registers as evil to the Ogre, the Ogre learns that they are evil."
			const imp = base.reminder('imp', 'ogre', 'Friend').do(madeEvil);
			expect(learns(imp)).toEqual([]);
		});

		it('does not apply with no Recluse on the script', () => {
			const others = ['ogre', 'imp', 'chef', 'empath', 'monk'];
			const plain = scenario(others, { script: scriptOf(others) })
				.reminder('imp', 'ogre', 'Friend')
				.do(madeEvil);
			expect(learns(plain)).toEqual([]);
		});
	});
});
